/* MindScore is derived game progress. Reports never change scores or diagnose health. */
window.TryvoMindScore=(()=>{
 const E=window.TryvoRescueEngine,esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 let host,busy=false,error='';
 function snapshot(s){
  const tram=E.valid(s.tram)?s.tram:null,history=tram?.history||[],sessions=new Map();
  for(const r of [...history,...Object.values(tram?.drafts||{})])for(const q of [r.obstacle,r.puzzle])if(q?.case?.sessionId&&q.case.review)sessions.set(q.case.review.level+':'+q.case.review.kind,{id:q.case.sessionId,c:q.case});
  let score=window.TryvoEngine.total(s),chatPoints=0,unknownPoints=0;
  for(const [key,a]of Object.entries(tram?.awards||{})){
   const [level,kind]=key.split(':');let eligible=false,supported=false,known=true;
   if(kind==='obstacle'||kind==='dispatch'){
    eligible=a.points===30;
    const field=kind==='obstacle'?'obstacle':'puzzle',q=[...history.filter(r=>r.level===level),tram.drafts[level]].filter(Boolean).map(r=>r[field]).find(q=>q?.solved&&q.firstPass&&!q.hint);
    known=!!q;supported=(q?.case?.turns||0)>0;
   }else{
    const runs=history.filter(r=>r.level===level),r=runs.find(r=>r.success);
    eligible=!!r&&!r.hint&&!r.obstacle.hint&&!r.puzzle.hint&&r.obstacle.firstPass&&r.puzzle.firstPass&&!runs.slice(0,runs.indexOf(r)).some(x=>!['checkpoint','arrived'].includes(x.reason));
    supported=(r?.obstacle.case?.turns||0)+(r?.puzzle.case?.turns||0)>0;
   }
   if(eligible){score+=a.points;if(!known)unknownPoints+=a.points;else if(supported)chatPoints+=a.points;}
  }
  const checks=s.history.filter(r=>r.taskId===window.TryvoData.check.id),rows=[...sessions.values()].map(({id,c})=>({id,level:c.review.level,kind:c.review.kind,score:c.review.score,turns:c.turns||0,attempt:c.review.attempt}));
  const game={mindScore:score,gamePoints:E.total(s),completedLevels:new Set(history.filter(r=>r.success).map(r=>r.level)).size,independentChecks:checks.length};
  return {score,chatPoints,unknownPoints,noChatPoints:score-chatPoints-unknownPoints,rows,checks,game,sessionIds:rows.map(r=>r.id),signature:JSON.stringify([game,rows])};
 }
 function card(s){const v=snapshot(s),r=s.practiceReport,stale=r&&r.signature!==v.signature;return `<section class="mindscore-card" aria-label="MindScore"><div class="mindscore-main"><span class="mindscore-trophy" aria-hidden="true">🏆</span><div><h2>MindScore</h2><p>Earned game progress. Your thinking, put into practice.</p></div><strong>${v.score}<small>points</small></strong></div><p class="mindscore-boundary">Not intelligence, brain health or proof of improvement.</p><div class="mindscore-actions"><span>${v.rows.length} reviewed case decisions · ${v.game.completedLevels} completed levels</span><button class="button" data-mind="open">${r?'Open my practice report':'View score & practice report'}</button></div><details><summary>What counts toward MindScore?</summary><p>First-pass, unhinted case awards count once. Route awards count when both decisions were first-pass and unhinted, with no earlier failed route test or route nudge. Existing eligible investigation points also count. Replays, later successful submissions and older route layouts do not add MindScore. Your broader game-point leaderboard is unchanged.</p><p>Client questions are recorded separately; no recorded client chat does not prove independence. Compare task results only under equivalent support conditions. ${stale?'New activity is available. Update your saved report when ready.':''}</p></details></section>`;}
 function contents(){const s=host.getState(),v=snapshot(s),saved=s.practiceReport,r=saved?.report,stale=saved&&saved.signature!==v.signature;
  return `<div class="mind-report"><div class="mind-report-lead"><strong>${v.score}<small>MindScore</small></strong><p>Accumulated eligible game points.<br>Your task results and use of assistance stay separate.</p></div><div class="mind-support"><div><b>${v.noChatPoints}</b><span>No recorded client chat</span></div><div><b>${v.chatPoints}</b><span>With AI client chat</span></div>${v.unknownPoints?`<div><b>${v.unknownPoints}</b><span>Support not recorded</span></div>`:''}</div><p class="mind-caution">No client chat is not verified independence. AI reviews still provide feedback. Neither this score nor the report can tell whether AI is harming your mind or whether your brain needs a “reset”.</p>
  <div class="mind-report-toolbar"><div><h3>Your practice report</h3><p>${v.rows.length?'The AI coach reviews your saved first judgments, decisions, rubric feedback and recorded client-question counts.':'Complete one client-case review to get a report grounded in your own decisions.'}</p></div><button class="button" data-mind="generate" ${busy||!v.rows.length?'disabled':''}>${busy?'Preparing report…':!r?'Generate AI report':stale?'Update with new activity':'Refresh saved report'}</button></div><p class="caption">On request, fictional case records and game totals are sent to Groq. Identical reports are reused. AI observations can be mistaken; inspect the cited decisions.</p><div role="status" class="mind-status">${busy?'Reviewing your case evidence. Your points will not change.':''}</div>${error?`<p class="mind-error" role="alert">${esc(error)}</p>`:''}
  ${r?`<div class="mind-report-result"><p class="caption">Generated ${esc(new Date(r.created*1000).toLocaleString())} · ${r.records.length} case decisions${stale?' · New activity is not included yet':''}${r.missingSessions?' · '+r.missingSessions+' unavailable sessions omitted':''}</p><p class="mind-summary">${esc(r.summary)}</p><h3>What your attempts show</h3>${r.observations.map(o=>`<article class="mind-observation"><h4>${esc(o.title)}</h4><p>${esc(o.detail)}</p><details><summary>See the supporting decisions</summary>${o.recordIds.map(id=>{const source=r.records.find(x=>x.id===id);return source?`<p><strong>${esc(source.case)}</strong> · ${source.stage==='arrival'?'new development':'initial decision'} · ${source.score}/8 on that case rubric · ${source.clientQuestions} client questions · ${source.reviewCount} reviews</p><a href="#progress" data-mind="record" data-level="${esc(v.rows.find(x=>x.id===id)?.level||'')}">Open level record</a>`:'';}).join('')}</details></article>`).join('')}<h3>Your next three practice sessions</h3><ol class="mind-plan">${r.practicePlan.map(p=>`<li><h4>${esc(p.title)}</h4><p>${esc(p.action)}</p><p><strong>Done when:</strong> ${esc(p.check)}</p></li>`).join('')}</ol></div>`:''}
  <details class="mind-independent"><summary>Independent checks · ${v.checks.length} recorded</summary><p>${v.checks.length?'Scores on this separate task are shown individually. Repeating it changes familiarity; a higher score does not establish learning transfer.':'No separate independent check is recorded yet. Case completion alone does not show how you perform without help.'}</p>${v.checks.map(c=>`<p>${esc(new Date(c.date).toLocaleDateString())} · ${c.score}/100 on this task · ${c.replay?'replay':'first attempt'} · ${c.hint||c.external||c.mode==='coop'?'support recorded':'no support declared'}</p>`).join('')}<button class="button secondary" data-mind="check">Open separate check</button></details><p class="caption">To investigate improvement, use comparable unfamiliar tasks before and after practice, record assistance and account for other explanations. This prototype does not establish an AI effect.</p></div>`;
 }
 function open(){host.modal('Your MindScore & practice report',contents());document.querySelector('#dialog').classList.add('mind-dialog');}
 function paint(){if(document.querySelector('#dialog')?.open&&document.querySelector('.mind-report'))document.querySelector('.mind-report').outerHTML=contents();}
 async function generate(){if(busy)return;const s=host.getState(),v=snapshot(s);if(!v.rows.length)return;if(s.practiceReport?.signature===v.signature){error='';paint();return;}busy=true;error='';paint();const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),47000);try{const response=await fetch('/api/practice-report',{method:'POST',headers:{'Content-Type':'application/json','X-Tryvo-Client':'case-workbench'},body:JSON.stringify({sessionIds:v.sessionIds,game:v.game}),signal:controller.signal});let r;try{r=await response.json();}catch{throw Error('The AI report service is unavailable. Start the Tryvo AI server and retry.');}if(!response.ok)throw Error(r.error||'The report could not be generated. Your progress is unchanged.');if(host.getState()!==s)return;s.practiceReport={signature:v.signature,report:r};host.save();}catch(e){error=e.name==='AbortError'?'The report took too long. Retry to retrieve a completed report. Your progress is unchanged.':e.message;}finally{clearTimeout(timer);busy=false;paint();if(host.getState()===s)host.render(false);}}
 document.addEventListener('click',e=>{const b=e.target.closest('[data-mind]');if(!b||!host)return;const action=b.dataset.mind;if(action==='open')open();if(action==='generate')generate();if(action==='record'){e.preventDefault();document.querySelector('#dialog').close();host.navigate('#progress');const el=document.getElementById('progress-'+b.dataset.level);if(el){el.open=true;el.scrollIntoView({block:'start'});}}if(action==='check'){document.querySelector('#dialog').close();document.querySelector('[data-action="start"][data-id="'+window.TryvoData.check.id+'"]')?.click();}});
 document.querySelector('#dialog').addEventListener('close',()=>{if(!document.querySelector('#dialog').open)document.querySelector('#dialog').classList.remove('mind-dialog');});
 return {configure:api=>host=api,snapshot,card};
})();
